import { readFileSync } from 'node:fs';
import { expect, test } from '@playwright/test';
import {
  expectScores,
  fixRandomToBlue,
  playGameWithScoreOne,
  recordMessages,
  seenMessages,
  waitForServiceWorkerControl,
} from './helpers.ts';

const ORIGIN = 'http://localhost:4173';
const AUDIO_FAILED = 'לא ניתן להשמיע צלילים. אפשר להמשיך לשחק לפי האורות.';

// The precache list generated by the build, read from the real dist/sw.js.
function precacheUrls(): string[] {
  const sw = readFileSync('dist/sw.js', 'utf8');
  return [...sw.matchAll(/url:"([^"]+)"/g)].map((m) => `${ORIGIN}/simon/${m[1]}`);
}

test('after the cache is ready the whole game works without network', async ({ page, context }) => {
  const externalRequests: string[] = [];
  page.on('request', (request) => {
    if (!request.url().startsWith(`${ORIGIN}/`) && !request.url().startsWith('data:')) {
      externalRequests.push(request.url());
    }
  });
  await fixRandomToBlue(page);
  await recordMessages(page);

  await page.goto('./');
  await waitForServiceWorkerControl(page);

  // Worker is limited to the project path.
  const scope = await page.evaluate(async () => (await navigator.serviceWorker.getRegistration())?.scope);
  expect(scope).toBe(`${ORIGIN}/simon/`);

  // Every essential file is in the project's own cache.
  const expected = precacheUrls();
  expect(expected.filter((url) => url.endsWith('.woff2'))).toHaveLength(6);
  for (const name of ['index.html', 'manifest.webmanifest', 'icons/icon-192.png', 'icons/icon-512.png',
    'icons/icon-maskable-512.png', 'icons/apple-touch-icon-180.png', 'icons/icon.svg']) {
    expect(expected).toContain(`${ORIGIN}/simon/${name}`);
  }
  expect(expected.some((url) => /assets\/index-.*\.js$/.test(url))).toBe(true);
  expect(expected.some((url) => /assets\/index-.*\.css$/.test(url))).toBe(true);
  const cache = await page.evaluate(async () => {
    const names = await caches.keys();
    const urls: string[] = [];
    for (const name of names) {
      for (const request of await (await caches.open(name)).keys()) {
        urls.push(request.url.split('?')[0]);
      }
    }
    return { names, urls };
  });
  expect(cache.names.every((name) => name.startsWith('simon-memory'))).toBe(true);
  for (const url of expected) {
    expect(cache.urls).toContain(url);
  }

  // Go offline and reload in the same browser context.
  await context.setOffline(true);
  await page.reload();
  await expect(page.locator('#screen-home')).toBeVisible();
  await expect(page.locator('.status-bar')).toContainText('שלב: 0 מתוך 10');
  const heeboLoaded = await page.evaluate(async () => {
    await document.fonts.ready;
    return [...document.fonts].some((font) => font.family.includes('Heebo') && font.status === 'loaded');
  });
  expect(heeboLoaded).toBe(true);
  await expectScores(page, 'טרם שוחק משחק', 'טרם שוחק משחק');

  // Full game offline, with sound available and the score saved.
  await playGameWithScoreOne(page);
  expect(await seenMessages(page)).not.toContain(AUDIO_FAILED);
  await expectScores(page, '1', '1');

  // Reopen again without network: the scores are still there.
  await page.reload();
  await expect(page.locator('#screen-home')).toBeVisible();
  await expectScores(page, '1', '1');

  expect(externalRequests).toEqual([]);
});

test('if the service worker cannot register, the online game still works', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.addInitScript(() => {
    navigator.serviceWorker.register = () => Promise.reject(new Error('blocked for test'));
  });
  await fixRandomToBlue(page);
  await recordMessages(page);

  await page.goto('./');
  await playGameWithScoreOne(page);
  await expectScores(page, '1', '1');

  // No offline support in this case, and no new message was shown.
  expect(await page.evaluate(() => navigator.serviceWorker.controller)).toBeNull();
  const allowed = new Set(['', 'צפו ברצף', 'תורכם', 'טעות! התוצאה: 1', AUDIO_FAILED]);
  expect((await seenMessages(page)).filter((text) => !allowed.has(text))).toEqual([]);
  expect(errors).toEqual([]);
});

test('first visit without network and without cache does not load the game', async ({ page, context }) => {
  // Documents the limit: offline needs one successful visit first.
  await context.setOffline(true);
  await expect(page.goto('./')).rejects.toThrow();
});
